/**
 * @name 04_multiple_asciifiers
 * @description Basic example applying multiple asciifiers on various textures in parallel with p5.js and p5.asciify.
 * @author humanbydefinition
 * @link https://github.com/humanbydefinition/p5.asciify
 * 
 * This example demonstrates how to apply multiple asciifiers on various textures in parallel.
 * The pre-defined 'brightness' renderer by the default asciifier is used to asciify the canvas.
 * A custom asciifier is created and applied to a custom framebuffer.
 */

// Options for the default brightness asciifier
const DEFAULT_BRIGHTNESS_OPTIONS = {
  enabled: true,
  characters: " .:-=+*#%@",
  characterColor: "#ffffff",
  characterColorMode: 'sampled',
  backgroundColor: "#000000",
  backgroundColorMode: 'fixed',
  invertMode: false,
  fontSize: 16,
  rotationAngle: 0
};

// Options for the custom brightness asciifier
const CUSTOM_BRIGHTNESS_OPTIONS = {
  enabled: true,
  characters: " .:oO@",
  characterColor: "#ffffff",
  characterColorMode: 'sampled',
  backgroundColor: "#000000",
  backgroundColorMode: 'fixed',
  invertMode: true,
  fontSize: 32,
  rotationAngle: 0
};

// Define a variable to store the default `P5Asciifier` instance
let defaultAsciifier; 
// Define a variable to store the custom `P5Asciifier` instance
let customAsciifier; 
// Framebuffer the custom asciifier will asciify
let customFramebuffer; 

function setup() {
    setAttributes('antialias', false);
    createCanvas(windowWidth, windowHeight, WEBGL);
}

function setupAsciify() {
    // Fetch the default `P5Asciifier` instance provided by the library
    defaultAsciifier = p5asciify.asciifier();
    // Create a new asciifier instance and apply it to a custom framebuffer
    customFramebuffer = createFramebuffer();
    customAsciifier = p5asciify.add(customFramebuffer);
    // Set the font size for both asciifiers
    defaultAsciifier.fontSize(16);
    customAsciifier.fontSize(32);
    defaultAsciifier.renderers().get("brightness").update({
        enabled: true,
        characters: " .:-=+*#%@",
        characterColor: "#ffffff",
        characterColorMode: 'sampled',
        backgroundColor: "#000000",
        backgroundColorMode: 'fixed',
        invert: false,
        rotation: 0
    });
    customAsciifier.renderers().get("brightness").update({
        enabled: true,
        characters: " .:oO@",
        characterColor: "#ffffff",
        characterColorMode: 'sampled',
        backgroundColor: "#000000",
        backgroundColorMode: 'fixed',
        invert: true,
        rotation: 0
    });
    // Make the background of both asciifiers fully transparent.
    defaultAsciifier.background([0, 0, 0, 0]);
    customAsciifier.background([0, 0, 0, 0]);
}

// Function to calculate orientation towards mouse cursor
function orientTowardsMouse() {
    // Convert mouse coordinates to normalized device coordinates (-1 to 1)
    let mouseXNorm = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -1, 1);
    let mouseYNorm = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1, -1); // Flip Y for 3D coordinate system

    // Calculate rotation angles based on mouse position
    let rotationY = mouseXNorm * PI * 0.5; // Horizontal mouse movement affects Y rotation
    let rotationX = mouseYNorm * PI * 0.3; // Vertical mouse movement affects X rotation

    return { rotX: rotationX, rotY: rotationY };
}

function draw() {
    directionalLight(255, 255, 255, 0, 0, -1);

    // Get mouse-based rotation values
    let mouseRotation = orientTowardsMouse();

    // Draw anything on the custom framebuffer for the custom asciifier to asciify
    customFramebuffer.begin();
    clear();
    fill(255);

    // Combine frame-based animation with mouse orientation
    rotateX(mouseRotation.rotX);
    rotateY(mouseRotation.rotY);
    rotateZ(mouseRotation.rotY);
    box(400, 100, 100);
    customFramebuffer.end();

    // Draw anything on the canvas for the default asciifier to asciify
    clear();
    normalMaterial();

    // Combine frame-based animation with mouse orientation for torus
    rotateX(radians(frameCount * 2) + mouseRotation.rotX);
    rotateY(radians(frameCount) + mouseRotation.rotY);
    torus(150, 100);
}

function drawAsciify() {
    background(0); // Set the background to black, removing everything previously drawn
    // Draw both asciifier textures on top of each other
    image(defaultAsciifier.texture, -width / 2, -height / 2);
    image(customAsciifier.texture, -width / 2, -height / 2);
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}

